<style>
.report-head{display:flex;align-items:end;gap:.65rem;flex-wrap:wrap;margin-bottom:.8rem}.report-head .title{margin-right:auto}.report-filter{display:flex;align-items:end;gap:.5rem;flex-wrap:wrap}.report-filter label span{display:block;margin-bottom:.18rem;font-size:.65rem;font-weight:900;text-transform:uppercase;letter-spacing:.04em;color:#64748b}.report-filter input,.report-filter select{height:2.4rem;min-width:145px;border:1px solid #94a3b8;background:#fff;padding:0 .55rem;font-size:.82rem;outline:none}.report-filter input:focus,.report-filter select:focus{border-color:#047857;box-shadow:0 0 0 2px #d1fae5}.report-btn{height:2.4rem;border:1px solid #94a3b8;background:white;padding:0 .8rem;font-size:.76rem;font-weight:900;color:#334155}.report-btn.primary{background:#065f46;border-color:#065f46;color:white}.report-panel{border:1px solid #cbd5e1;background:#fff;box-shadow:0 1px 2px rgba(15,23,42,.05)}.report-table{width:100%;border-collapse:collapse;font-size:.79rem}.report-table th{position:sticky;top:0;background:#e2e8f0;border:1px solid #94a3b8;padding:.5rem .55rem;font-size:.68rem;text-transform:uppercase;color:#334155;white-space:nowrap}.report-table td{border:1px solid #d7dee7;padding:.5rem .55rem;vertical-align:top}.report-table tbody tr:hover td{background:#ecfdf5}.num{text-align:right;font-variant-numeric:tabular-nums}.report-summary{display:flex;justify-content:flex-end;gap:.65rem;flex-wrap:wrap;margin-top:.7rem}.report-summary>div{min-width:150px;border:1px solid #cbd5e1;background:#fff;padding:.55rem .7rem}.report-summary small{display:block;text-transform:uppercase;font-weight:900;color:#64748b}.report-summary b{display:block;margin-top:.15rem;font-size:1.05rem}.positive{color:#047857}.negative{color:#b91c1c}
